  ?dept <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#name> ?name .
  { ?person <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#memberOf> ?dept . } UNION { ?person <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#worksFor> ?dept . }
} GROUP BY ?name HAVING(COUNT(DISTINCT ?person) > 500.0 && COUNT(DISTINCT ?person) < 570.0) ORDER BY ?value
